# Let's build a mapping from song_id to a "title by artist(s)" string for matching with old_song_titles.
# We'll also build a reverse mapping from playlist_id to the song_ids that match old_song_titles (to remove), and a set of all song_ids to add to "Archived Songs".

def song_title_artist_string(song):
    # Compose "Title by Artist1, Artist2"
    artist_names = ", ".join(artist["name"] for artist in song["artists"])
    return f"{song['title']} by {artist_names}"

# Build song_id -> "title by artist(s)" mapping
song_id_to_title_artist = {sid: song_title_artist_string(song) for sid, song in song_id_to_details.items()}

# Find song_ids to archive (those whose "title by artist(s)" is in old_song_titles)
archived_song_ids = set()
for sid, title_artist in song_id_to_title_artist.items():
    if title_artist in old_song_titles:
        archived_song_ids.add(sid)

# For each playlist, find which song_ids to remove (those in archived_song_ids)
playlist_removals = {}
for playlist_id, song_ids in playlist_id_to_song_ids.items():
    to_remove = [sid for sid in song_ids if sid in archived_song_ids]
    if to_remove:
        playlist_removals[playlist_id] = to_remove

print({"archived_song_ids": list(archived_song_ids), "playlist_removals": playlist_removals})

